if('IntersectionObserver' in window){document.body.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(element=>observer.observe(element))}
addEventListener('scroll',()=>{const total=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress').style.width=`${total>0?scrollY/total*100:0}%`},{passive:true});
const modal=document.querySelector('#modal');const dialogs={convite:'<h2>Um convite de <em>Cleópatra.</em></h2><p>“Durante séculos, minha imagem foi associada à sedução, ao fascínio e ao poder. Mas uma imagem, por si só, não revela toda a força de um símbolo.</p><p>É preciso conhecer seu significado. Sentir sua presença. Permitir que ele ganhe vida na sua imaginação.</p><p>Agora, eu convido você a percorrer sete experiências. Sete camadas para explorar o magnetismo, a sensualidade, a estratégia e a soberania que meu nome representa.”</p><small>Roteiro da personagem ficcional. O vídeo de apresentação ainda não foi fornecido.</small>',previa:'<h2>Uma atmosfera para <em>mergulhar.</em></h2><p>A direção visual combina sombras profundas, luz dourada, símbolos egípcios e movimentos lentos. Cada portal representa uma etapa da jornada.</p><p>Na versão final, este espaço receberá uma demonstração autêntica de 20 a 40 segundos de uma ativação, com narrativa e atmosfera sonora.</p><small>Esta é uma apresentação visual do protótipo, não uma ativação do método.</small>',inscricao:'<h2>Sua jornada está <em>desenhada.</em></h2><p>Este botão demonstra o caminho de inscrição. O checkout será conectado após a definição do preço, das condições de pagamento, da plataforma, do prazo de acesso e da garantia.</p><small>Protótipo visual. Nenhuma cobrança ou coleta de dados é realizada.</small>'};
document.querySelectorAll('[data-dialog]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#modal-content').innerHTML=dialogs[button.dataset.dialog];modal.showModal()}));document.querySelector('.modal-close').addEventListener('click',()=>modal.close());modal.addEventListener('click',event=>{if(event.target===modal){const rect=modal.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)modal.close()}});
